  ui_story_5076_50760200_4_dialog_content = "ฉันจะบอกคุณนะ, ในช่วงหลายปีที่ผ่านมา...",
  ui_story_5076_50760200_5_dialog_content = "กบฏ! ข้าพเจ้า, ในนามของกองทัพนอร์ทวินด์, มาที่นี่เพื่อให้โอกาสแก่พวกคุณ: การสนับสนุนของคุณถูกตัดออก; ยอมแพ้ทันที!",
  ui_story_5076_50760200_6_dialog_content = "ฝันต่อไปเถอะ! ตราบใดที่เมืองนี้ยังยืนยัน เราจะไม่แพ้...",
  ui_story_5076_50760200_7_dialog_content = "นักธนู! ยิง! ใครสักคน พาพวกนั้นมาที่นี่! ให้พวกเขาป้องกันการโจมตี!",
  ui_story_5076_50760200_8_dialog_content = "กองพลแรกหรือ? แล้วไงล่ะ? ด้วยตัวประกันทั้งหลายที่เรามีอยู่ในเมืองนี้...",
  ui_story_5076_50760200_9_dialog_content = "กัปตัน ดูสิ! พวกเขากำลังบุกโจมตีเราด้วยโล่ที่ถือสูง!",
  ui_story_5076_50760200_10_dialog_content = "อะไร? พวกมันคิดว่าตัวเองเป็นอมตะหรือ? ยิงต่อไป! อย่าให้พวกมันเข้าใกล้กำแพงเมืองเลย!",
  ui_story_5076_50760200_11_dialog_content = "เอื้อออ—!",
  ui_story_5076_50760200_12_dialog_content = "เกิดอะไรขึ้นข้างล่างรึเปล่า?",
  ui_story_5076_50760200_13_dialog_content = "ทีมหนึ่งเข้ามาจากด้านหลังในช่วงที่สับสน! พวกเขาอยู่ในเมืองแล้ว!",
  ui_story_5076_50760200_14_dialog_content = "มันมีอยู่เท่าไหร่?",
  ui_story_5076_50760200_15_dialog_content = "เพียงหยิบมือเท่านั้น แต่ละคนถือดาบเพียงเล่มเดียว - พวกเขาปีนผนังด้วยมือเปล่าของตัวเอง!",
  ui_story_5076_50760200_16_dialog_content = "กลุ่มไร้ประโยชน์! ฉันต้องจัดการเองหรือเปล่า?!",
  ui_story_5076_50760200_17_dialog_content = "แต่... ผู้นำพวกนั้นแข็งแกร่งมาก...",
  ui_story_5076_50760200_18_dialog_content = "หยุดต่อต้าน! ฉันจะไม่ทำร้ายพลเรือนที่ไม่มีอาวุธ!",
  ui_story_5076_50760200_19_dialog_content = "คุณก็เป็นพลเมืองของราชอาณาจักรนี้เช่นกัน ดังนั้นโปรดหยุดทำร้ายเพื่อนร่วมชาติของคุณ!",
  ui_story_5076_50760200_20_dialog_content = "โง่เขลาทั้งหลาย ถูกล้อมรอบโดยพวกเราแล้วยังทำท่าแข็ง... จับพวกมันเถอะ!",
  ui_story_5076_50760200_21_dialog_content = "คุณมีโอกาสแล้ว วายร้ายทั้งหลาย—ทั้งหมด ฆ่าศัตรูที่เห็นซะ!",
  ui_story_5076_50760200_22_dialog_content = "สั่งการผู้นำของพวกเขาและเปิดทางให้พี่น้องทั้งหลายที่กำลังโจมตีเมือง! ตามฉันมา!",
  ui_story_5076_50760200_23_dialog_content = "หยุดพวกมัน! เรียกนักยิงธนูมาที่นี่!",
  ui_story_5076_50760200_24_dialog_content = "กัปตัน ข่าวไม่ดีครับ! มีคนบุกเข้าไปในถ้ำที่เรากักตัวชาวเมือง และโกดังของเรากำลังอัคคีภัยครับ!",
  ui_story_5076_50760200_25_dialog_content = "กัปตัน! ประตูทางตะวันตกถูกเปิด; มีคนกำลังช่วยพลเรือนหนี!",
  ui_story_5076_50760200_26_dialog_content = "ก-กัปตัน! ด้านหลังเรา!",
  ui_story_5076_50760200_27_dialog_content = "<size=40>คำสาป!</size> ทำไมมันถึงเกิดขึ้นอีกครั้ง—!",
  ui_story_5076_50760200_28_dialog_content = "<size=45>ไปตายซะให้หมด!</size>",
  ui_story_5076_50760200_29_dialog_content = "หัวหน้า!",
  ui_story_5076_50760200_30_dialog_content = "กบฏ! หัวหน้าของคุณตายแล้ว! วางอาวุธลงทั้งหมดของคุณ!",
  ui_story_5076_50760200_31_dialog_content = "การฆ่าฆ่าตายที่ไร้สาระในเมืองนี้มีมากพอแล้ว แต่ตอนนี้เป็นเวลาที่จะสิ้นสุดมันลง! ไม่มีใครต้องตายอีกถ้าคุณนำผู้นำของคุณมาหาฉัน!",
  ui_story_5076_50760200_32_dialog_content = "ทำไมเราจะต้องเชื่อคุณ? หลักฐานของคุณคืออะไร...",
  ui_story_5076_50760200_33_dialog_content = "เพราะฉันคืออาดราส!",
  ui_story_5076_50760200_34_dialog_content = "ผู้ชายที่จะยุติสงครามนี้!",
  ui_story_5076_50760200_35_dialog_content = "ดูสิ เขาวิ่งเร็วขนาดนั้น! หรือว่าเขาก็เข้าร่วมการสำรวจด้วยเหรอ?",
  ui_story_5076_50760200_36_dialog_content = "ถ้าฮีโร่คนนั้นกำลังจะไปที่นั่นด้วย ลูกชายของฉันที่อยู่ในกองทัพควรจะปลอดภัยขึ้น ใช่มั้ย...?",
  ui_story_5076_50760200_37_dialog_content = "คุณลืมหรือเปล่า? พระเอกกำลังจะแต่งงาน; พิธีกรรมก็เตรียมพร้อมทั้งหมดแล้ว",
  ui_story_5076_50760200_38_dialog_content = "มาร์เซลา!",
  ui_story_5076_50760200_39_dialog_content = "หวา! อย่าทำให้ฉันตกใจแบบนั้นสิ! เกิดอะไรขึ้นเหรอ?",
  ui_story_5076_50760200_40_dialog_content = "ฉันไม่ได้ให้คุณรอนานเกินไป... ใช่ไหม?",
  ui_story_5076_50760200_41_dialog_content = "ฉันสบายดี ฉันกำลังกังวลเกี่ยวกับคุณ มีอะไรเกิดขึ้นในกองทัพหรือเปล่า",
  ui_story_5076_50760200_42_dialog_content = "อิคลิพไซท์เริ่มมีการรวมตัวในภาคเหนือ และผู้นำทัพมีคำสั่งให้กำจัดพวกมันออกไป",
  ui_story_5076_50760200_43_dialog_content = "แล้วคุณไม่ไปเหรอ?",
  ui_story_5076_50760200_44_dialog_content = "พลเอกอคิลลิสบอกว่าจำนวนของพวกเขาไม่จำเป็นต้องมีฉันอยู่ ท่านให้ฉันพักงานเพื่อที่เราจะได้ใช้เวลาในงานแต่งงานของเราอย่างสงบสุข",
