  ui_story_5076_50760200_50_dialog_content = "งานแต่งงานกำลังจะถึงแล้ว และคุณสองคนก็ต้องการที่จะไปเที่ยวนอกเมืองอย่างกะทันหันเหรอ?",
  ui_story_5076_50760200_51_dialog_content = "เอ่อ? ฉันแค่คิดว่าเราจะยุ่งในอีกสองสามวันข้างหน้า ดังนั้นฉันต้องการเตรียมวัสดุการสอนเพียงพอสำหรับลูกเล็กเด็กแดง",
  ui_story_5076_50760200_52_dialog_content = "และคุณไม่สามารถทิ้งงานนั้นให้ฉันจัดการได้หรือ?",
  ui_story_5076_50760200_53_dialog_content = "คุณไม่ไปเดินทางไปที่ใหม่ใช่ไหม? นอกจากนี้ คุณช่วยฉันมามากพอแล้วด้วยการรวบรวมมัน ฉันไม่สามารถพึ่งพาคุณได้ตลอดเวลา",
  ui_story_5076_50760200_54_dialog_content = "กำลังจะออกเดินทางอีกครั้งใช่ไหม? ดูแลตัวเองดีๆนะ ลูดวีส",
  ui_story_5076_50760200_55_dialog_content = "เช่นกันนะคุณทั้งสอง... สถานเลี้ยงเด็กกำพร้าดูดีขึ้นเยอะในครั้งนี้ คุณจริงจังทุ่มเททุกอย่างให้มันเลยใช่ไหม Adras?",
