  ui_story_5076_50760200_58_dialog_content = "การทำขนมปัง",
  ui_story_5076_50760200_59_dialog_content = "รูปทรงที่หรูหราจริงๆ มันไม่เข้ากับคุณเลยนะ คุณรู้ไหม",
