  ui_story_5076_50760200_72_dialog_content = "อาดราสไม่รู้จะจัดการกับเด็ก ๆ อย่างไร แต่คุณก็สามารถทำให้พวกเขาฟังด้วยเพียงไม่กี่คำเท่านั้น",
