  ui_story_5076_50760502_4_dialog_content = "คุณทั้งหมดปลอดภัยแล้ว ดังนั้นโปรดสงบ ฉันทำการรักษาทางหนีไว้เรียบร้อยแล้ว",
  ui_story_5076_50760502_5_dialog_content = "ทุกคนไม่เป็นไรนะ? มีใครบาดเจ็บหรือตายมั้ย?",
  ui_story_5076_50760502_6_dialog_content = "ยังมีพื้นที่อื่นๆที่ต้องการความช่วยเหลืออีกหรือไม่คะ?",
  ui_story_5076_50760502_7_dialog_content = "ไม่, ผู้บัญชาการอาดราส, เราคือทหารรักษาการณ์ด้านหลัง; คนอื่นๆ ได้หนีผ่านทางผ่านไปแล้ว",
  ui_story_5076_50760502_8_dialog_content = "ขอขอบคุณมาร์เซล่าทั้งหมด; เธอได้กระตุ้นให้เราปกป้องเมือง และนั่นเป็นเหตุผลว่าทำไมเราถึงอดทนได้มาจนถึงวันนี้",
  ui_story_5076_50760502_9_dialog_content = "ถ้าคุณมาที่นี่ช้ากว่านี้ ทุกคนอาจจะ...แล้ว",
  ui_story_5076_50760502_10_dialog_content = "Marcela...? เธออยู่ที่ไหนตอนนี้? เธอหนีไปแล้วหรือยัง?",
  ui_story_5076_50760502_11_dialog_content = "ฮะ? คุณไม่ได้เจอมาร์เซลาระหว่างทางมาที่นี่เหรอ?",
  ui_story_5076_50760502_12_dialog_content = "เพื่อซื้อเวลาให้ทุกคนสามารถถอยหลังได้ เธอนำหน่วยรบหน้าไปใกล้วัดเพื่อดึงความสนใจอิคลิพไซท์...",
  ui_story_5076_50760502_13_dialog_content = "ไม่... ไม่...",
  ui_story_5076_50760502_14_dialog_content = "อย่าทำให้ฉันกลัวแบบนี้นะที่รัก—",
  ui_story_5076_50760502_15_dialog_content = "เดี๋ยวนะ อาดราส! ให้ฉันลองจับตำแหน่งของเธอดูสักหน่อย!",
  ui_story_5076_50760502_16_dialog_content = "ได้โปรดเถอะ ลูดไวส์...",
  ui_story_5076_50760502_17_dialog_content = "ไม่มีความจำเป็นที่ทุกคนต้องตามฉัน! ถอยกลับและปกป้งประชาชนในเมือง—",
  ui_story_5076_50760502_18_dialog_content = "ฉันไม่สามารถคัดกรองความคิดและความรู้สึกที่ยุ่งเหยิงทั้งหมดได้ ที่ฉันรู้ได้เพียงว่ามีอิคลิพไซท์กำลังรวมตัวที่ทิศตะวันออกของวัด",
  ui_story_5076_50760502_19_dialog_content = "ออกไปให้พ้น สัตว์ประหลาดเน่าๆ!",
  ui_story_5076_50760502_20_dialog_content = "เร็วขึ้น! ฉันต้องรีบขึ้น!!!",
  ui_story_5076_50760502_21_dialog_content = "ที่นี่—",
  ui_story_5076_50760502_22_dialog_content = "คนที่อยู่บนพื้นนั้นอยู่กับกองกำลังชาวบ้าน ทัศนียภาพที่น่าเกลียดชัง...",
  ui_story_5076_50760502_23_dialog_content = "พวกเขาก็สามารถฆ่าอิคลิพไซท์ได้มากมายที่ด้านหน้าด้วย",
  ui_story_5076_50760502_24_dialog_content = "น่าเสียดาย แต่ที่นี่ไม่สามารถรักษาได้แล้ว—",
  ui_story_5076_50760502_25_dialog_content = "อ้าว! ไม่... นี่คือออกัสทิน... เป็นไปไม่ได้นี่.",
  ui_story_5076_50760502_26_dialog_content = "ทหารที่กล้าหาญและมีเกียรติ... ขอให้วิญญาณของพวกคุณสุดท้ายจงรู้จักความสงบสุข",
  ui_story_5076_50760502_27_dialog_content = "... อิคลิพไซท์เน่าๆ.",
  ui_story_5076_50760502_28_dialog_content = "มาร์เซลา! คุณได้ยินฉันไหม?!",
  ui_story_5076_50760502_29_dialog_content = "ไม่ต้องห่วง ฉันกำลังจะมาหาคุณ!",
  ui_story_5076_50760502_30_dialog_content = "(ป-เปล่า—)",
  ui_story_5076_50760502_31_dialog_content = "ใคร? นั่นใครน่ะ?",
  ui_story_5076_50760502_32_dialog_content = "(มีคนอยู่ในหัวฉัน พูดกับฉัน... หรือเพราะบาดแผลที่ฉันได้รับก่อนหน้านี้เหรอ?)",
  ui_story_5076_50760502_33_dialog_content = "(คุณต้องตื่นขึ้นมา—)",
  ui_story_5076_50760502_34_dialog_content = "(อย่าดูจนจบ—)",
  ui_story_5076_50760502_35_dialog_content = "ว่าไง",
  ui_story_5076_50760502_36_dialog_content = "<size=40>ไม่... ไม่นะ!!!</size>",
  ui_story_5076_50760502_37_dialog_content = "อาดราส???",
  ui_story_5076_50760502_38_dialog_content = "อ๊าก, หัวของฉัน... มันทำให้ฉันเจ็บมาก.",
  ui_story_5076_50760502_39_dialog_content = "<size=40>อย่าทำให้ฉันกลัวแบบนี้นะ มาร์เซลา—</size>",
  ui_story_5076_50760502_40_dialog_content = "<color=#FFB400><size=45>มาร์เซลา!!!</size></color>",
  ui_story_5076_50760502_41_dialog_content = "เกิดอะไรขึ้น...",
  ui_story_5076_50760502_42_dialog_content = "อาดราส, มาร์เซลา...",
  ui_story_5076_50760502_43_dialog_content = "รอฉันด้วย...",
  ui_story_5076_50760502_44_dialog_content = "!!!",
  ui_story_5076_50760502_45_dialog_content = "ขอบคุณพระเจ้า—",
  ui_story_5076_50760502_46_dialog_content = "เพื่อที่จะไม่ขโมยคนที่ฉันรักจากฉัน, มาร์เซลาที่รักของฉัน—",
  ui_story_5076_50760502_47_dialog_content = "มาร์เซลา! นี่ฉัน ฉันอยู่ตรงนี้! ฉันกลับมาแล้ว ดังที่ฉันสัญญาไว้.",
  ui_story_5076_50760502_48_dialog_content = "ไม่ต้องกังวลนะ พวกเรากำลังจะกลับบ้านแล้ว...",
  ui_story_5076_50760502_49_dialog_content = "(ความทรงจำคือ—)",
  ui_story_5076_50760502_50_dialog_content = "<color=#FFB400>(คำสาป.)</color>",
  ui_story_5076_50760502_51_dialog_content = "(แต่ตอนนี้... กรุณาอย่ามาขวางทางการพบกันของพวกเขานะ)",
  ui_story_5076_50760502_52_dialog_content = "เสียงในหัวฉัน... คุณคือใคร...?",
  ui_story_5076_50760502_53_dialog_content = "ในที่สุดคุณก็กลับมา อาดราส",
  ui_story_5076_50760502_54_dialog_content = "ฉันรอคุณ...มานานเกินไปแล้ว",
  ui_story_5076_50760502_55_dialog_content = "เก็บแรงไว้นะครับ ที่รัก ฉันจะหาคนมาดูแลแผลของคุณก่อนที่เราจะกลับบ้าน",
  ui_story_5076_50760502_56_dialog_content = "สองถังไวน์ที่คุณทิ้งไว้ให้ฉัน... ฉันได้แบ่งปันไวน์พวกนั้นให้ทุกคน",
  ui_story_5076_50760502_57_dialog_content = "พวกเขาทุกคนบอกว่ามันอร่อยมาก และความหวานของมันทำให้พวกเขารู้สึกมีความสุขมาก",
  ui_story_5076_50760502_58_dialog_content = "นั่นเพราะเราไม่เคยกลัว แม้แต่ช่วงเวลาสั้น ๆ—",
  ui_story_5076_50760502_59_dialog_content = "อาดราส... ทุกครั้งที่ฉันคิดถึงคุณ ใจฉันเต็มไปด้วยความหวัง",
  ui_story_5076_50760502_60_dialog_content = "ขอบคุณที่รักษาสัญญาของคุณ",
  ui_story_5076_50760600_1_dialog_content = "<color=#e8d9bb>เมืองที่เคยถูกปีศาจทำลาย ตอนนี้กำลังกอบกู้ในยุคการสร้างสรรค์ใหม่ ศรัทธาที่มาจากวีรบุรุษเติมเต็มความหวังให้กับชาวเมือง</color>",
  ui_story_5076_50760600_2_dialog_content = "<color=#e8d9bb>แต่ก็ยังมีหลายคนที่ไม่มีที่อยู่อาศัย แม้ว่าบรรยากาศจะเจริญรุ่งเรือง</color>",
  ui_story_5076_50760600_3_dialog_content = "ระวังเมื่อย้ายซากปรักษ์และระวังคนเดินเท้าด้วยนะ! ถ้าคุณต้องการความช่วยเหลือ ขอให้ทหารเลเยียนช่วยเถอะ!",
  ui_story_5076_50760600_4_dialog_content = "ขอรับ",
  ui_story_5076_50760600_5_dialog_content = "ไปกันเถอะ",
  ui_story_5076_50760600_6_dialog_content = "...เอาสิ",
  ui_story_5076_50760600_7_dialog_content = "อาดราส อะไร...?",
  ui_story_5076_50760600_8_dialog_content = "มันไม่เป็นไร พวกเราแค่จะไปเดินเล่น",
  ui_story_5076_50760600_9_dialog_content = "\"เรา\"? โอ้... โอ้! โปรดอย่ากังวลมากเกินไป; เราจะสร้างสรรค์ใหม่เสร็จสมบูรณ์เร็วๆ นี้",
  ui_story_5076_50760600_10_dialog_content = "มาร์เซลา? ฉันคิดว่าคุณเป็นเพื่อนกับผู้ชายคนนั้น... ทำไมคุณไม่ทักทายเขาเลยล่ะ?",
  ui_story_5076_50760600_11_dialog_content = "... ไม่เป็นไร ไปกันต่อเถอะ",
  ui_story_5076_50760600_12_dialog_content = "คุณอยากไปที่ไหน? โบสถ์ หรือเปล่า?",
  ui_story_5076_50760600_13_dialog_content = "ไม่! ไปที่ไหนก็ได้แต่ไม่ใช่วัด! ฉัน... ยังกลัวที่นั่นอยู่.",
  ui_story_5076_50760600_14_dialog_content = "ไม่เป็นไร เราสามารถไปที่อื่นได้ ทำไมเราไม่ไปเยี่ยมเด็ก ๆ ล่ะ? พวกเขาทำได้ดี แต่ฉันแน่ใจว่าคุณยังกังวลเกี่ยวกับพวกเขา",
  ui_story_5076_50760600_15_dialog_content = "ฉันเจอเขาแล้ว อคิลลิส เขาอยู่ที่นี่",
  ui_story_5076_50760600_16_dialog_content = "...",
  ui_story_5076_50760600_17_dialog_content = "อาดราส... คุณสบายดีไหม?",
  ui_story_5076_50760600_18_dialog_content = "... ลูดวีส?",
  ui_story_5076_50760600_19_dialog_content = "การต่อสู้จบลงแล้ว อาดราส ทำไมเธอยังอยู่ที่นี่?",
  ui_story_5076_50760600_20_dialog_content = "ไม่มีใครเหลือที่จะป้องกันที่นี่ ฉันต้องปกป้องคนที่นี่",
  ui_story_5076_50760600_21_dialog_content = "อ๊ะ! อย่ากลัวนะ มาร์เซลา! แค่พลเอกอคิลลีสเอง",
  ui_story_5076_50760600_22_dialog_content = "ขอโทษนะ แต่การต่อสู้ทำให้มาร์เซล่าเหนื่อยมาก โปรดยกโทษให้เธอถ้าเธอกลัวจนไม่กล้าทักทาย",
  ui_story_5076_50760600_23_dialog_content = "อาดราส, มาร์เซลาคือ—",
  ui_story_5076_50760600_24_dialog_content = "อคิลลีส!",
  ui_story_5076_50760600_25_dialog_content = "มันคืออะไร? คุณสองคนทำตัวแปลก ๆ อยู่ โดยเฉพาะคุณ Ludweiss ทำไมคุณไม่มาเยี่ยม Marcela บ่อยๆ หน่อย?",
  ui_story_5076_50760600_26_dialog_content = "... มองมาที่ฉันสิ อาดราส.",
  ui_story_5076_50760600_27_dialog_content = "ใช่ไหม? โอ้ ก่อนที่ฉันจะลืม... Eclipsites ที่แนวหน้าถูกจัดการหรือยัง? เราสามารถสนุกสนานอย่างสงบได้ใหม่หรือไม่?",
  ui_story_5076_50760600_28_dialog_content = "เราสามารถขับ Eclipsites กลับไปทางทิศเหนือ แต่ยังไม่สามารถทำอะไรกับหลุมลึกที่เราพบที่นั่นได้",
  ui_story_5076_50760600_29_dialog_content = "คุณยินดีที่จะกลับไปสู้อีกครั้งหรือไม่ อาดราส?",
  ui_story_5076_50760600_30_dialog_content = "แน่นอน หน้าที่ของฉันก็คือการปกป้องบ้านและประเทศของฉันอยู่แล้วน่ะ",
  ui_story_5076_50760600_31_dialog_content = "คุณยินยอมให้ฉันกลับไปสู้ศึกใช่ไหม มาร์เซลา? ไม่ต้องกังวล ฉันจะทำตามสัญญาที่ให้กับคุณเสมอ",
  ui_story_5076_50760600_32_dialog_content = "...",
  ui_story_5076_50760600_33_dialog_content = "Ludweiss, คุณเคยบอกฉันว่าความรักคือแหล่งกำเนิดของพลังเคเลสไทต์ ด้วยแรงขับเคลื่อนจากความรู้สึก คุณและพวกคุณได้สร้างสิ่งที่ไม่ธรรมดาขึ้นมา",
  ui_story_5076_50760600_34_dialog_content = "บอกฉันสิ, มีวิธีใดที่สามารถสกัดอารมณ์ของ Aurorian และเก็บรักษาไว้ได้หรือไม่?",
  ui_story_5076_50760600_35_dialog_content = "คุณเสนออะไรกันแน่?",
  ui_story_5076_50760600_36_dialog_content = "ตอนนี้ อาดราสต้องการการกระตุ้นจากความเกลียดชังและความแค้น เพื่อจะลุกขึ้นมาทำอะไรสักอย่าง แต่ฉันไม่ต้องการให้ความรักในหัวใจของเขาถูกกลืนกลายด้วยความเกลียดชังนั้น",
  ui_story_5076_50760600_37_dialog_content = "คุณสองคนกำลังพูดถึงอะไรในโลกนี้?",
  ui_story_5076_50760600_38_dialog_content = "ลูดวิส ฉันต้องการทราบว่ามีวิธีใดที่สามารถดึงความรักนั้นออกมาและเก็บรักษาไว้ได้หรือไม่",
  ui_story_5076_50760600_39_dialog_content = "ฉันเข้าใจแล้ว... ฉันจะคิดอย่างอื่น",
  ui_story_5076_50760600_40_dialog_content = "อาดราส คุณยินดีที่จะให้ข้ายืมโล่และพลังของคุณอีกครั้งไหม?",
  ui_story_5076_50760600_41_dialog_content = "มันก็แน่อยู่แล้ว!",
  ui_story_5076_50760600_42_dialog_content = "คุณเกลียด Eclipsites มากแค่ไหน? คุณยินดีที่จะอุทิศชีวิตและทุกอย่างที่คุณมีเพื่อการทำลายล้างพวกเขาอย่างสิ้นเชิงหรือไม่?",
  ui_story_5076_50760600_43_dialog_content = "อิคลิพไซท์... ไม่ต้องพูดถึงเลย! ในหัวใจของฉันมีแต่ความเกลียดชังเท่านั้น...",
  ui_story_5076_50760600_44_dialog_content = "แม้จะมีน้ำหนักของนิรันดร์บนไหล่ของคุณ คุณสาบานที่จะต่อสู้กับความชั่วร้ายด้วยใจทั้งหมดของคุณจนกว่าจะไม่มีอะไรเหลืออยู่หรือไม่?",
  ui_story_5076_50760600_45_dialog_content = "ฉัน... ฉันสาบาน.",
  ui_story_5076_50760600_46_dialog_content = "แล้วก็ ในนามของทหารที่ภูมิใจและตัวข้าพเจ้าเอง ชีวิตของเราอยู่ในมือที่สามารถของคุณอีกครั้ง",
  ui_story_5076_50760600_47_dialog_content = "ยินดีต้อนรับกลับมาปฏิบัติหน้าที่อาดราส",
  ui_story_5076_50760600_48_dialog_content = "ยินดีต้อนรับกลับมาสู่สงคราม",
  ui_story_5076_50760600_49_dialog_content = "เริ่มจากตรงไหนดีล่ะ?",
  ui_story_5076_50760600_50_dialog_content = "เพื่อกำจัดหุบเขาน้ำแข็งทางเหนือ ศาลราชวงศ์ได้เสนอวิธีใหม่ในการเพิ่มพลังของเรา",
  ui_story_5076_50760600_51_dialog_content = "โครงการที่จะกินเราเข้าไป แต่ไม่ก่อนที่เราจะกำจัดความชั่วร้ายทั้งหมดออกจากโลกของเรา",
  ui_story_5076_50760600_52_dialog_content = "และชื่อของโครงการนั้นคือ—",
  ui_story_5076_50760600_53_dialog_content = "<color=#FFB400>นักล่าผู้เงียบงัน.</color>",
  ui_story_5076_50760701_1_dialog_content = "<color=#e8d9bb>หลังจากที่ได้รับความสำเร็จอย่างยิ่งใหญ่ในสนามรบหลัก กองทหารราชวังได้กระจายกำลังไปทั่วและขับไล่กลับ โดยมุ่งมั่นที่จะคืนครองเมืองที่ถูกอิคลิพไซท์บุกครอง</color>",
  ui_story_5076_50760701_2_dialog_content = "<color=#e8d9bb>ในหมู่พวกเขา บางคนถูกลดลงจนเหลือเพียง \"รัง\" ของอิคลิพไซท์</color>",
  ui_story_5076_50760701_3_dialog_content = "<color=#e8d9bb>ในเวลานั้น \"ฮีโร่\" ที่มีหน้ากากใหม่จะขึ้นสู่เวที</color>",
  ui_story_5076_50760701_4_dialog_content = "รายงาน! การยืนยันจากการยามแสดงให้เห็นว่าสภาพภายในเมือง - มันถูกทำลายอย่างสมบูรณ์ ด้วยอิคลิพไซท์ที่กำลังวิ่งเต็มที่!",
  ui_story_5076_50760701_5_dialog_content = "และคนทั้งหลายล่ะ? มีร่องรอยของการรอดชีวิตของพวกเขาไหม?",
  ui_story_5076_50760701_6_dialog_content = "... ไม่มีใครรอดชีวิต",
  ui_story_5076_50760701_7_dialog_content = "หยุดการโจมตี ทหารของคุณไม่มีทางสู้เข้าไปในเมืองได้",
  ui_story_5076_50760701_8_dialog_content = "Eclipsites ไม่รู้จักกับความกลัว หากเราไม่ทำให้เมืองนี้พังทลายลงบนหัวของพวกเขา พวกเขาจะไม่ถอยหลัง",
  ui_story_5076_50760701_9_dialog_content = "แล้วก็... ไม่, กัปตัน, เราควรทำอย่างไรต่อไป?",
  ui_story_5076_50760701_10_dialog_content = "หนึ่งในสมาชิกทีมของฉันกำลังเดินทางอยู่แล้ว ให้กำลังที่เหลือของคุณรออยู่ที่ด้านหลัง",
  ui_story_5076_50760701_11_dialog_content = "คุณหมายถึง... อ๊า!",
  ui_story_5076_50760701_12_dialog_content = "นายที่นั่น ทหาร นายกำลังขวางทางฉันอยู่ ขอให้นายย้ายไปทางขวาหน่อย",
  ui_story_5076_50760701_13_dialog_content = "<color=#e8d9bb>ปฏิบัติตามคำสั่งของผู้บัญชาการที่ไม่คุ้นเคย ทหารย้ายตัวเล็กน้อยไปด้านข้าง และแสงสว่างจากสายฟ้าพุ่งออกมาจากปลายนิ้วของเธอ ทำลายประตูเมืองที่ต้านทานการโจมตีที่ยืดเยื้อของพวกเขา</color>",
  ui_story_5076_50760701_14_dialog_content = "ประตูอาจจะเปิดอยู่ แต่ยังมีอิคลิพไซท์ที่ฉลาดอยู่เยอะมากอยู่เบื้องหลังกำแพงเมือง ฉันจะทิ้งพวกเขาไว้ให้คุณ... ซินเธีย.",
  ui_story_5076_50760701_15_dialog_content = "<color=#e8d9bb>ด้วยคันธนูยาวที่ตึงเคร่งเหมือนพระจันทร์เสี้ยว วีรบุรุษในสีเขียวสดใสปล่อยลูกศรอย่างงามงาม ทุกครั้งที่เธอดึงสายธนู อิคลิพไซท์ที่เชี่ยวชาญในการโจมตีระยะไกลจะตกหนึ่งต่อหนึ่ง</color>",
  ui_story_5076_50760701_16_dialog_content = "ยิงได้ดีมาก! คุณต้องได้รบกวนพวกเขามากจริงๆ ด้วยการโจมตีครั้งล่าสุดนั้น เพราะพวกเขาเริ่มหลั่นออกมาจากประตูแล้ว",
  ui_story_5076_50760701_17_dialog_content = "อยู่กับฉัน อัศวิน! เรากำลังจะชาร์จเข้าสู่การรบ!",
  ui_story_5076_50760701_18_dialog_content = "อัศวินไม่มีโอกาสต่อต้านอิคลิพไซท์ยักษ์เหล่านั้นได้เลย Freya.",
  ui_story_5076_50760701_19_dialog_content = "พวกเขาจะปลอดภัย! ฟรีกสัน - คลื่นแรกมอบให้คุณทั้งหมด!",
  ui_story_5076_50760701_20_dialog_content = "<color=#e8d9bb>ด้วยคำพูดที่ส resonant ของเธอ ไฟลุกโชนไกลๆ ลุกโชนอย่างรุนแรงและไร้ความเมตตากลืนกินสัตว์ประหลาดที่กล้ามแน่น</color>",
  ui_story_5076_50760701_21_dialog_content = "<color=#e8d9bb>เมืองที่กองกำลังธรรมดาอาจต้องใช้เวลาหลายวันในการทำลาย ก็ถูกพวกเขาครอบครองได้ง่ายดาย</color>",
  ui_story_5076_50760701_22_dialog_content = "<color=#e8d9bb>ทหารม้าที่นำโดยซายนต์ฟริยาที่เงียบสงบได้ย่ำยีอิคลิพไซท์โดยไม่ต้องพยายาม หอกของเธอกวาดผ่านไปด้วยความเหนือชั้น อิคลิพไซท์ที่ตกลงมาถูกล้อมรอบด้วยลิ้นไฟอย่างรวดเร็ว ซึ่งทรมานในความทุกข์ยาก</color>",
  ui_story_5076_50760701_23_dialog_content = "โหดร้ายจริง ๆ... ไม่มีความจำเป็นที่จะล้อเล่นกับพวกเขาแบบนี้ Friegson.",
  ui_story_5076_50760701_24_dialog_content = "อิคลิพไซท์ไม่ควรได้รับความเห็นใจเลย",
  ui_story_5076_50760701_25_dialog_content = "รองกัปตันอยู่ที่ไหน?",
  ui_story_5076_50760701_26_dialog_content = "อิคลิพไซท์กำลังถอนตัวเข้าไปในเมือง ดูเหมือนว่าพวกมันสามารถรู้สึกความกลัวได้หลังจากทั้งหมด... แต่ฉันแน่ใจว่าเขากำลังรอพวกมันอยู่ในที่นั่นแล้ว",
  ui_story_5076_50760701_27_dialog_content = "ถ้าพวกเขาไม่หนี อย่างน้อยพวกเขาก็จะได้รับความตายอย่างใจดี... นั่นมากกว่าที่พวกเขาควรได้รับ",
  ui_story_5076_50760701_28_dialog_content = "<color=#e8d9bb>... ขณะที่อิคลิพไซท์ ถูกขับเคลื่อนด้วยความกลัวแบบธรรมชาติ หนีไปทางประตูด้านหลัง มีหนึ่งรูปทรงยืนอยู่คนเดียวเพื่อขวางทางของพวกเขา</color>",
  ui_story_5076_50760701_29_dialog_content = "<color=#e8d9bb>เวทย์มนต์น้ำที่ไร้ความปราณี ร่วมกับดาบยักษ์ที่หนาวเย็น ทำลายผู้ที่กล้าที่จะก้าวหน้าได้โดยไม่ต้องพยายาม ทำให้อิคลิพไซท์ไม่มีทางหนี.</color>",
  ui_story_5076_50760701_30_dialog_content = "ศัตรูทั้งหมดจงตาย... ศัตรูทั้งหมดจงตาย... ศัตรูทั้งหมดจงตาย...",
  ui_story_5076_50760701_31_dialog_content = "อิคลิพไซท์! <size=45>ตายซะ!!!</size>",
  ui_story_5076_50760702_1_dialog_content = "อิคลิพไซท์—ตาย—",
  ui_story_5076_50760702_2_dialog_content = "ทุกคนต้องตาย!",
  ui_story_5076_50760702_3_dialog_content = "ใจเย็นๆ อาดราส... คุณกำลังทำให้ทหารกลัวนะ",
  ui_story_5076_50760702_4_dialog_content = "เอ็ม-มาร์เซลา? ถอยไป, ที่นี่อันตรายนะ!",
  ui_story_5076_50760702_5_dialog_content = "นั่นมัน... นักล่าผู้เงียบงันเหรอเนี่ย?",
  ui_story_5076_50760702_6_dialog_content = "น่ากลัวมาก ยากที่จะเชื่อว่าเขาคือฮีโร่ตำนาน ดูที่เขาสิ! เขาเป็นอย่าง...",
  ui_story_5076_50760702_7_dialog_content = "เงียบ ๆ หน่อย; เขาอาจจะได้ยินเรานะ",
  ui_story_5076_50760702_8_dialog_content = "การต่อสู้จบแล้วเหรอ? ทุกคนปลอดภัยแล้วใช่ไหม?",
  ui_story_5076_50760702_9_dialog_content = "คุณทำได้ดีมาก อาดราส",
  ui_story_5076_50760702_10_dialog_content = "แต่... ไม่มีผู้รอดชีวิตเดียวในเมืองนี้... อิคลิพไซท์ที่เน่าเปื่อยเหล่านั้น.",
  ui_story_5076_50760702_11_dialog_content = "ไม่ใช่ความผิดของคุณ ส่วนทีมอื่นกำลังมาแล้ว ตอนนี้เราไปกันเถอะ",
  ui_story_5076_50760702_12_dialog_content = "...",
  ui_story_5076_50760702_13_dialog_content = "อีกหนึ่งการฉลองรอบกองไฟสำหรับนักล่าผู้เงียบงัน!",
  ui_story_5076_50760702_14_dialog_content = "อย่างนั้นเหรอ? ฉันจำไม่ได้ว่าฉันเป็นส่วนหนึ่งของทีม หรือแม้กระทั่งแอนโทนี",
  ui_story_5076_50760702_15_dialog_content = "คุณควรจะกลับไปแอนโทนี ถ้าคุณยังคงอยู่รอบ ๆ พวกเรา คนอื่น ๆ จะเริ่มกลัวคุณเองเช่นกัน",
  ui_story_5076_50760702_16_dialog_content = "ขอโทษนะ นายพลอคิลลิส คุณเป็นฮีโร่ แต่...",
  ui_story_5076_50760702_17_dialog_content = "ฉันไม่ใช่นายพลอีกต่อไปแล้ว แอนโทนี คุณไม่จำเป็นต้องเรียกฉันเหมือนฉันยังเป็น",
  ui_story_5076_50760702_18_dialog_content = "แต่กลับ...",
  ui_story_5076_50760702_19_dialog_content = "ที่นี่ไม่มีทั้งนายพลหรือผู้บัญชาการ เพียงแค่นักล่าผู้เงียบงันเท่านั้น",
  ui_story_5076_50760702_20_dialog_content = "อย่าอ้อมค้อมนะ แอนโทนี ถ้าเธออยากจะมากินกับเรา ก็บอกมาเถอะ",
  ui_story_5076_50760702_21_dialog_content = "อ้อเหรอ...",
  ui_story_5076_50760702_22_dialog_content = "เฮ้ ลูดไวส์ อย่ากินเนื้อที่ปรุงรสแล้วทั้งหมดคนเดียวนะ!",
  ui_story_5076_50760702_23_dialog_content = "มันเป็นเรื่องใหญ่อะไร? แค่ขอให้ Friegson ทำเพิ่มให้คุณก็ได้.",
  ui_story_5076_50760702_24_dialog_content = "เธอแค่จะเผาทุกอย่างให้เป็นเถ้าเท่านั้น คุณคนโง่ นอกจากนี้ฉันก็ไม่ต้องการอะไรที่เธอทำอาหารเลย",
  ui_story_5076_50760702_25_dialog_content = "คุณมีอะไรจะพูดกับฉันเหรอ?",
  ui_story_5076_50760702_26_dialog_content = "สิ่งที่เธอหมายคือ เธอไม่อยากทานอะไรที่ถูกปรุงโดยไฟที่เธอใช้ฆ่าอิคลิพไซท์",
  ui_story_5076_50760702_27_dialog_content = "ใช่แล้ว!",
  ui_story_5076_50760702_28_dialog_content = "ฉันจะไปที่อื่นทานอาหาร",
  ui_story_5076_50760702_29_dialog_content = "ไม่, รอสักครู่! ฉันแค่หยอกเล่น... อืม, ทุกอย่างนี้เป็นความผิดของคุณทั้งหมด, ซินเธีย.",
  ui_story_5076_50760702_30_dialog_content = "ฉันแค่ช่วยคุณพูดในสิ่งที่คุณคิดเท่านั้นเอง",
  ui_story_5076_50760702_31_dialog_content = "เราไม่ควรทะเลาะกันขณะที่เรากำลังทานอาหาร—นี่ กินเพิ่มเถอะ",
  ui_story_5076_50760702_32_dialog_content = "ว้าว, ฉันรู้สึกถึงใจมาก! คุณคือเหตุผลหลักที่ทำให้ฉันเลือกเข้าร่วมกับนักล่าผู้เงียบงัน",
  ui_story_5076_50760702_33_dialog_content = "ฉันคิดว่าคุณบอกว่ามันเพื่อปกป้องราชอาณาจักรและประชาชน...",
  ui_story_5076_50760702_34_dialog_content = "\"นักบุญที่เงียบสงบ\" หรือ... ฉันคิดไม่ออกว่าจะมีชื่อที่ไม่เหมาะสมกับคุณมากกว่านี้แล้ว",
  ui_story_5076_50760702_35_dialog_content = "อืม, ฉันอิ่มแล้ว! ฉันคงควรเริ่มทำงานวันนี้แล้วนะ...",
  ui_story_5076_50760702_36_dialog_content = "อะไร เขียนบันทึกอยู่อีกเหรอ",
  ui_story_5076_50760702_37_dialog_content = "ในวันที่ฉันออกจากบ้าน ฉันตัดสินใจจะบันทึกทุกอย่างเกี่ยวกับการเดินทางของฉัน ฉันไม่ได้ยอมแพ้ในสิ่งที่เช่นนี้ได้ง่ายๆ",
  ui_story_5076_50760702_38_dialog_content = "แต่ตั้งแต่ที่ Adras ได้ช่วยฉันหนีออกจาก Eclipsites, ฉันยังไม่เคยเดินทางออกนอกราชอาณาจักร",
  ui_story_5076_50760702_39_dialog_content = "ยังมีสถานที่ที่ฉันอยากไปเยอะมาก แต่ฉันก็เจออิคลิพไซท์ทันทีที่เริ่มเดินทางอีกครั้ง นั่นคือเวลาที่คุณช่วยฉัน, ฟรียา—",
  ui_story_5076_50760702_40_dialog_content = "และหลังจากติดอยู่ที่นี่นานเกินไป บันทึกของฉันตอนนี้เป็นเกี่ยวกับคุณและเพื่อนร่วมทีมของคุณ",
  ui_story_5076_50760702_41_dialog_content = "คุณได้แน่ใจที่จะเขียนเกี่ยวกับวีรกรรมของฉันในวันนี้หรือยัง?",
  ui_story_5076_50760702_42_dialog_content = "ฉันกำลังจะทำอยู่นี่แหละ คุณจะให้พื้นที่ฉันบ้างไหม? คุณจะทำให้หมึกฉันหกทั่วไปนะ—",
  ui_story_5076_50760702_43_dialog_content = "ฉันประหลาดใจที่คุณยังสามารถร่าเริงได้หลังจากเห็นความหายนะที่เกิดขึ้นวันนี้",
  ui_story_5076_50760702_44_dialog_content = "เอาเป็นว่า ถ้าพิจารณาว่าคุณคือผู้อยู่เบื้องหลังการทำลายล้างส่วนใหญ่...",
  ui_story_5076_50760702_45_dialog_content = "พอแล้ว ฟรียา ฉันก็มีส่วนรับผิดชอบในการต่อสู้ของวันนี้ด้วย",
  ui_story_5076_50760702_46_dialog_content = "เธอก็พูดถูกนะ ฟรีกสัน",
  ui_story_5076_50760702_47_dialog_content = "คุณไม่ควรทำให้ตัวเองเครียดมากเกินไปในการต่อสู้ แม้แต่สายธนูที่แข็งแกร่งที่สุดก็จะขาดหากถูกกดดันมากเกินไป",
  ui_story_5076_50760702_48_dialog_content = "ฟรีกซันได้อยู่ข้างฉันมานานแล้ว... ก่อนที่ฉันจะได้รับการสถานที่ในภาคเหนือ เราทั้งสองเคยรับใช้เป็นทหารยามในพระราชวัง",
  ui_story_5076_50760702_49_dialog_content = "เมื่อเทียบกับคุณทุกคนที่ชินกับการเห็นการต่อสู้แบบนี้ นางยังต้องปรับตัวอีกบ้าง",
  ui_story_5076_50760702_50_dialog_content = "ในฐานะผู้มีชั้นชนเกิด ฉันแน่ใจว่าคุณตลอดมามองสนามรบเป็นสถานที่ของเกียรติยศและความรุ่งโรจน์, ฟรียา แต่คุณต้องเข้าใจว่าเพื่อที่จะเอาชีวิต คุณต้องพร้อมที่จะสละชีวิตของคุณเอง",
