  ui_story_5076_50760800_27_dialog_content = "อืมม...",
  ui_story_5076_50760800_28_dialog_content = "ขออภัยนะ อาดราส และ... มาร์-มาร์เซลา.",
  ui_story_5076_50760800_29_dialog_content = "อาดราส วันนี้กลับมาจากชานเมืองแล้วเหรอ?",
  ui_story_5076_50760800_30_dialog_content = "Adras, องุ่นเหล่านี้มาจากไร่องุ่นของเราเอง รับไป; รสชาติดีและเหมาะสำหรับการทำไวน์มาก.",
  ui_story_5076_50760800_31_dialog_content = "เพื่อนๆ ทางนี้หน่อย! อัดราส ลองดูผ้านี้สิ มันเหมาะสำหรับทำเสื้อผ้าใหม่ให้มาร์เซลามากเลย.",
  ui_story_5076_50760800_32_dialog_content = "คุณจริงๆ ไม่จำเป็นต้องทำเลยนะ ถ้าคุณทำ มาร์เซล่าจะไม่ปล่อยให้ฉันได้ยินจบถ้าคุณทำ.",
  ui_story_5076_50760800_33_dialog_content = "อ๊ะ—มาร์เซลา?",
  ui_story_5076_50760800_34_dialog_content = "คุณไปไหนมาที่รัก?",
  ui_story_5076_50760800_35_dialog_content = "...ฉันเห็นเธอวิ่งกลับมา!",
  ui_story_5076_50760800_36_dialog_content = "เออ, เธอคงจะขี้อายนะ ฮ่าฮ่า!",
  ui_story_5076_50760800_37_dialog_content = "หรืออาจเป็นเพราะเธอโกรธ นี่เป็นความผิดของเธอทั้งหมดนะ",
  ui_story_5076_50760800_38_dialog_content = "ไปกันเถอะ; ปล่อยพื้นที่ส่วนตัวให้กับฮีโร่ที่แข็งแกร่งของเราบ้างนะ, โอเคไหม?",
  ui_story_5076_50760800_39_dialog_content = "ขอโทษนะลูดไวส์ คนที่นี่บางครั้งอาจจะมากไปหน่อย แต่เธอกำลังพูดถึงอะไรนะ—",
  ui_story_5076_50760800_40_dialog_content = "ลูดวีส? ว-ทำไมคุณถึงร้องไห้...? เป็นอะไรรึเปล่า?",
  ui_story_5076_50760800_41_dialog_content = "ฉ...ฉัน...ฉันสบายดี แค่... แค่ฉันรู้สึกประทับใจจริง ๆ กับสิ่งที่เพิ่งเกิดขึ้นเท่านั้นเอง.",
  ui_story_5076_50760800_42_dialog_content = "ทุกคนดูแลคุณทั้งคู่ดีมาก... ฉันดีใจมากสำหรับคุณ",
  ui_story_5076_50760800_43_dialog_content = "นั่นเพราะพวกเขาทั้งหมดเป็นคนดี",
  ui_story_5076_50760800_44_dialog_content = "ฉันรู้... พวกเขาจริง ๆ แล้วเป็นคนดี...",
  ui_story_5076_50760800_45_dialog_content = "นี่คือผ้าเช็ดหน้า รับไปสิ",
  ui_story_5076_50760800_46_dialog_content = "รู้สึกดีขึ้นหรือยัง?",
  ui_story_5076_50760800_47_dialog_content = "ใช่ ขอบคุณนะ อาดราส—",
  ui_story_5076_50760800_48_dialog_content = "คุณพูดถึงเรื่องจดหมาย กัปตันมีคำสั่งใหม่ให้ฉันหรือเปล่า?",
  ui_story_5076_50760800_49_dialog_content = "... พระราชากำลังเตรียมการสำหรับการสำรวจใหม่ พระองค์ต้องการทำลายแหล่งที่มาของความชั่วร้าย",
  ui_story_5076_50760800_50_dialog_content = "ครั้งนี้ เขาส่งคุณและ Silent Hunters ไปจัดการกับนรกที่ค้นพบครั้งแรกทางทิศเหนือ",
  ui_story_5076_50760800_51_dialog_content = "ดังนั้น, โลกยังไม่สงบสุข",
  ui_story_5076_50760800_52_dialog_content = "ฉันยอมรับ",
  ui_story_5076_50760800_53_dialog_content = "จะมีกำลังอื่น ๆ เข้าร่วมกับนักล่าผู้เงียบงันในการรณรงค์นี้หรือไม่?",
  ui_story_5076_50760800_54_dialog_content = "จากที่ฉันทราบ มีกองพลสองกองที่ได้รับมอบหมายไปยังที่นั้นด้วยค่ะ",
  ui_story_5076_50760800_55_dialog_content = "ใครจะเป็นผู้นำพวกเขาเหรอ?",
  ui_story_5076_50760800_56_dialog_content = "นี่คือพระคัมภีร์ลูเซียส... เขาได้รับการคืนตำแหน่งจากพระราชา ไม่เพียงเท่านั้น เขายังจะรับผิดชอบการบัญชาการทั้งหมดในการสำรวจทั้งหมด",
  ui_story_5076_50760800_57_dialog_content = "อะไร? ไอ้คนทรยศชั่วนั่นหรือ?!",
  ui_story_5076_50760800_58_dialog_content = "แต่เขาได้รวบรวมกำลังทหารส่วนตัวของตนเองในสงครามครั้งสุดท้าย! ผู้คนจำนวนมากเสียชีวิตเพราะเขา!",
  ui_story_5076_50760800_59_dialog_content = "ทุกเมืองที่ไม่มีใครรอดชีวิตนั้นเป็นผลมาจากความผิดของเขา! คุณหมายความว่าคุณจะบอกฉันว่าคนนี้กำลังควบคุมการดำเนินงานของเราหรือเปล่า?!",
  ui_story_5076_50760800_60_dialog_content = "เป็นความผิดของเขาที่ทำให้คนหลายคนที่ไม่มีความผิดต้องตาย! มาร์เซล่าก็เกือบจะสูญเสียชีวิตเพราะเขาด้วย!",
  ui_story_5076_50760800_61_dialog_content = "ไม่! เขาไม่คู่ควรได้รับความเมตตา! ฉันจะไม่ยกโทษให้เขาเพราะ—",
  ui_story_5076_50760800_62_dialog_content = "กรุณาใจเย็นๆ อาดราส นี่คือคำสั่งของพระราชา",
  ui_story_5076_50760800_63_dialog_content = "แม้กระนั้น ฉันก็ยังไม่ยอมทำงานให้กับคนอย่าง Lucius!",
  ui_story_5076_50760800_64_dialog_content = "สาปแช่งเขา—",
  ui_story_5076_50760800_65_dialog_content = "อย่ารับความไม่พอใจของคุณออกที่ลัดไวส์ อาดราสนะ",
  ui_story_5076_50760800_66_dialog_content = "มาร์เซลา? คุณกลับมาแล้ว...",
  ui_story_5076_50760800_67_dialog_content = "ราชาอาจถูกล้อมรอบด้วยคนที่โกหกและคนที่เคารพ... แต่พวกเขาไม่ใช่คนที่คุณได้ปกป้องมาตลอดเวลาใช่ไหม?",
  ui_story_5076_50760800_68_dialog_content = "หรือคุณต้องการเห็นเมืองของเราถูกทำลายครั้งที่สองหรือไม่?",
  ui_story_5076_50760800_69_dialog_content = "สำหรับพระราชาที่จะยอมลดความภาคภูมิใจและปล่อยให้ลูเซียสได้รับเกียรติในการรณรงค์นี้จะเพียงแค่ช่วยสนับสนุนเป้าหมายชั่วร้ายของเขามากขึ้นเท่านั้น",
  ui_story_5076_50760800_70_dialog_content = "แต่แม้ว่ามันจะทำให้ฉันเจ็บปวด ฉันก็ไม่มีทางปฏิเสธเขาได้",
  ui_story_5076_50760800_71_dialog_content = "กัปตันต้องการฉัน, พันธมิตรของฉันต้องการฉัน... และประชาชนผู้บริสุทธิ์ของราชอาณาจักรของเราต้องการฉัน...",
  ui_story_5076_50760800_72_dialog_content = "... ฉันยอมรับคำสั่งของฉัน, Ludweiss.",
  ui_story_5076_50760800_73_dialog_content = "เมื่อลูกๆและฉันตัดสินใจเรื่องสถานที่ใหม่สำหรับสถานเลี้ยงเด็กกำพร้าแล้ว ฉันจะรวบรวมอุปกรณ์ของฉันและออกเดินทางทันที",
  ui_story_5076_50760800_74_dialog_content = "เข้าใจแล้ว... ขอบคุณ Adras.",
  ui_story_5076_50760800_75_dialog_content = "ขอบคุณ... ที่ยังคงสู้เพื่อโลกนี้",
  ui_story_5076_50760800_76_dialog_content = "แล้วคุณล่ะ? แนวทางการดำเนินการต่อไปของคุณคืออะไร?",
  ui_story_5076_50760800_77_dialog_content = "ฉัน...? อืม, ฉันอยากจะเห็นออโรราด้วยตัวเองนะ—",
  ui_story_5076_50760800_78_dialog_content = "การสำรวจครั้งนี้จะอันตรายมาก คุณไม่ควรมาด้วยครั้งนี้จะดีที่สุด",
  ui_story_5076_50760800_79_dialog_content = "คุณควรออกจากที่นี้ ลูดไวส์",
  ui_story_5076_50760800_80_dialog_content = "โลกนี้เป็นสถานที่ที่กว้างใหญ่และน่าทึ่ง ฉันแน่ใจว่าคุณจะพบสถานที่ที่น่าสนใจมากกว่าในการเขียนบันทึกของคุณ",
  ui_story_5076_50760800_81_dialog_content = "... ขอโทษ แต่ฉันยังไม่สามารถออกไปได้ ฉันยังมีเรื่องที่ต้องจัดการที่นี่",
  ui_story_5076_50760800_82_dialog_content = "นอกจากนี้ ฉันก็ไม่รู้สึกว่าจะเป็นไรถ้าอยู่และเป็นเพื่อนกับมาร์เซลา ใช่มั้ย มาร์เซลา?",
  ui_story_5076_50760800_83_dialog_content = "เอาล่ะ ฉันจะฝากเธอไว้ในมือคุณ ลูดไวส์",
  ui_story_5076_50760800_84_dialog_content = "กลับมาเร็วที่สุดที่เธอทำได้นะ ไม่รู้เลยว่าฉันจะเปลี่ยนใจเมื่อไหร่ รู้ยัง!",
  ui_story_5076_50760800_85_dialog_content = "แล้วฉันจะสัญญากับคุณเหมือนที่ฉันสัญญากับเธอ—",
  ui_story_5076_50760800_86_dialog_content = "ไม่ว่าจะเกิดอะไรขึ้น ฉันจะกลับมานะ",
  ui_story_5076_50760800_87_dialog_content = "และถ้าฉันบังเอิญพบกับแสงออโรราในระหว่างการเดินทางของฉัน—",
  ui_story_5076_50760800_88_dialog_content = "ฉันจะแน่นอนที่จะบอกคุณทุกอย่างเกี่ยวกับความงามของมัน ครับเพื่อน",
  ui_story_5076_50760800_89_dialog_content = "ดูเหมือนว่าเรามีข้อตกลง... ฉันรอไม่ไหวที่จะได้ยินเรื่องราวของคุณ โอ้ วีรบุรุษที่ยิ่งใหญ่",
  ui_story_5076_50760900_1_dialog_content = "\"เวลามักจะผ่านไปเมื่อเราไม่ได้สังเกต... และไม่นานหลังจากนั้น—\"",
  ui_story_5076_50760900_2_dialog_content = "ครูลัดไวส์ ออกมาที่นี่เร็ว!",
  ui_story_5076_50760900_3_dialog_content = "เกิดอะไรขึ้นกับเรื่องราวทั้งหมดนี้? ฉันแทบจะไม่มีโอกาสเขียนในไดอารี่ของฉันในวันนี้เลยนะ...คุณรู้ไหม?",
  ui_story_5076_50760900_4_dialog_content = "ไม่เจอกันนานเลยนะ ลัดไวส์",
  ui_story_5076_50760900_5_dialog_content = "อาดราส? คุณ...",
  ui_story_5076_50760900_6_dialog_content = "เฮ้... ยินดีต้อนรับกลับบ้านนะ อาดราส.",
  ui_story_5076_50760900_7_dialog_content = "รีบปิดประตูสิลูกๆ! ถ้ามีใครเห็นว่าฮีโร่ทรงพลังของเรากลับมาแล้ว ทั้งเมืองจะทับทวนที่นี่จนเป็นฝุ่น!",
  ui_story_5076_50760900_8_dialog_content = "เด็ก ๆ บอกฉันว่าคุณได้จัดการสถานเลี้ยงเด็กกำพร้ามาเป็นเวลาหนึ่งแล้ว ฉันขอบคุณคุณมากสำหรับความช่วยเหลือของคุณเพื่อนของฉัน",
  ui_story_5076_50760900_9_dialog_content = "ฉันไม่เคยคิดว่าการเลี้ยงดูเด็กๆ จำนวนมากจะยากขนาดนี้ มาร์เซล่าทำได้ยังไงนะ— คอห์, คอห์, คอห์!",
  ui_story_5076_50760900_10_dialog_content = "นึกถึงแล้ว หล่อนอยู่ที่ไหนนะ? ลูกเล็กเด็กแดงบอกว่าฉันอาจจะหาเจอหล่อนที่นี่กับคุณ.",
  ui_story_5076_50760900_11_dialog_content = "หา? กับฉันเหรอ?",
  ui_story_5076_50760900_12_dialog_content = "อ๊ะ! เธอเห็นฉันเขียนบันทึกในสมุดของฉัน แล้วเธอก็เพิ่งออกไปเมื่อกี้.",
  ui_story_5076_50760900_13_dialog_content = "ขอโทษด้วยนะ ฉันรู้ว่าคุณคงอยากเห็นเธอมาก...",
  ui_story_5076_50760900_14_dialog_content = "ไม่เป็นไรนะ ลัดไวส์ ตราบใดที่ฉันยังถือดาบนี้อยู่ในมือ นางก็ไม่เคยห่างจากฉันไปไหนเลย",
  ui_story_5076_50760900_15_dialog_content = "การสำรวจภาคเหนือนั้นยาวนาน แต่ยังไม่พอที่จะแยกหัวใจของเราออกจากกัน",
  ui_story_5076_50760900_16_dialog_content = "แต่ก็รู้สึกไม่สบายใจนิดหน่อยที่ไม่ได้ยินเสียงเธอหลังจากการเดินทางที่ยาวนาน... คุณรู้ไหมว่าเธอจะกลับมาเมื่อไหร่?",
  ui_story_5076_50760900_17_dialog_content = "ฉันไม่แน่ใจ—นี่เตือนฉันได้ว่า เราได้ยินข่าวการกลับมาอย่างชัยชนะของคุณเมื่อไม่กี่วันที่ผ่านมา! ฉันได้ยินว่าพระราชาได้สรรเสริญคุณทั้งหมดเนื่องจากความสำเร็จของคุณ.",
  ui_story_5076_50760900_18_dialog_content = "ถูกต้อง พวกเราทุกคนก็ได้รับชื่อใหม่ด้วย",
  ui_story_5076_50760900_19_dialog_content = "ฉันจำได้ว่าฉันเคยอ่านเรื่องนั้นในจดหมายของ Freya ด้วย!",
  ui_story_5076_50760900_20_dialog_content = "ยศของคุณตอนนี้คือ \"รีกัล\" ใช่ไหม? และเฟรย่าคือ \"เรเควียม,\" ฟรีกสันคือ \"ฟรอสต์ไฟร์,\" และซินเธียคือ \"มิธอส.\"",
  ui_story_5076_50760900_21_dialog_content = "แต่เธอลืมบอกฉันถึงตำแหน่งของอคิลลีสนะ",
  ui_story_5076_50760900_22_dialog_content = "\"เคลย์มอร์\" นั่นคือฉายาใหม่ของกัปตันอคิลลิส",
  ui_story_5076_50760900_23_dialog_content = "ฟรีย่าบอกว่าพวกเขาให้มงกุฎจากใบโคลอสให้เธอด้วย มงกุฎของคุณอยู่ที่ไหน?",
  ui_story_5076_50760900_24_dialog_content = "ฉันลดมันลงแล้ว",
  ui_story_5076_50760900_25_dialog_content = "หือ? ทำไมล่ะ?",
  ui_story_5076_50760900_26_dialog_content = "มงกุฎดอกไม้ที่ฉันสวมเข้าสู่สนามรบได้รับมาหลายปีที่แล้ว เมื่อฉันสิ้นสุดสงครามต่อต้านกบฏ ในเวลานั้น ฉันได้รับรางวัลทั้งความรักและเกียรติยศ",
  ui_story_5076_50760900_27_dialog_content = "นั่นเป็นเหตุผลที่...ฉันไม่ต้องการอีกตัวหนึ่ง.",
  ui_story_5076_50760900_28_dialog_content = "อืม, นี่คือความเสียดาย ฉันอยากจะเห็นทุกคนได้รับรางวัลสำหรับความพยายามของพวกเขา",
  ui_story_5076_50760900_29_dialog_content = "แม้ว่าฉันจะปฏิเสธมงกุฎอีกหนึ่งอัน ฉันก็ยังขอรางวัลจากกษัตริย์ในรูปแบบของที่ดินและเงิน",
  ui_story_5076_50760900_30_dialog_content = "ช่างมีประโยชน์จริง ๆ ของคุณนะ!",
