  ui_story_5076_50761102_28_dialog_content = "คุณได้ยินด้วยตัวเอง: ฟรีกซันถูกโจมตี และมีความเป็นไปได้ว่าผู้รับผิดชอบอยู่ในศาลราชวัง! การส่งเธอไปที่นั่นก็ไม่ต่างจากการส่งเธอไปสู่ความตาย!",
  ui_story_5076_50761102_29_dialog_content = "ถูกต้องแล้ว ต้องเป็นลูเซียสแน่นอน! เขามักจะต่อต้านเราเสมอ และตอนนี้เขากำลังกำจัดเราทีละคน...",
  ui_story_5076_50761102_30_dialog_content = "ไม่ว่าจะเป็นยังไงก็ตาม รองกัปตัน ไม่ได้มีบ้านให้กลับไปอยู่แล้วน่ะ...",
  ui_story_5076_50761102_31_dialog_content = "ไม่ นี่ไม่ยุติธรรมต่อคุณ! มือของลูเซียสอยู่ที่คอของเพื่อนเราแล้ว กัปตัน คุณจะปล่อยให้สถานการณ์นี้ดำเนินต่อไปอีกนานแค่ไหน?",
  ui_story_5076_50761102_32_dialog_content = "เราต้อง...หยุดเขา...",
  ui_story_5076_50761102_33_dialog_content = "ใจเย็นก่อน อาดราส! ฟรียาและซินเธียยังถูกเฝ้าดูอยู่!",
  ui_story_5076_50761102_34_dialog_content = "คุณยังต้องคิดถึงเมืองทั้งเมืองและประชาชน... ตอนนี้ไม่ใช่เวลาที่จะตัดสินใจอย่างเสี่ยง",
  ui_story_5076_50761102_35_dialog_content = "เราต้องร่วมมือกันและหาทางเพื่อพิสูจน์ความบริสุทธิ์ของ Friegson นะ เข้าใจไหม?",
  ui_story_5076_50761102_36_dialog_content = "กัปตัน... ทำไมคุณไม่พูดอะไรเลย? คุณเคยปกป้องลูกน้องที่ต่ำที่สุดของคุณ แต่ตอนนี้คุณแม้แต่ไม่ยกนิ้วเพื่อป้องกันเพื่อนที่ใกล้ชิดที่สุดของคุณเลยหรือ?",
  ui_story_5076_50761102_37_dialog_content = "กัปตัน... ทำไม...",
  ui_story_5076_50761102_38_dialog_content = "อาดราส, ฟรีกซัน... ฉันขอโทษ.",
  ui_story_5076_50761102_39_dialog_content = "ค่าใช้จ่ายในการกู้คืนความสงบสุขให้กับราชอาณาจักรของเรามันสูงเกินไป เราไม่สามารถปล่อยให้มันตกอยู่ในความวุ่นวายอีกครั้งได้",
  ui_story_5076_50761102_40_dialog_content = "ถ้าข้าเลือกที่จะต่อสู้ สภาผู้อาวุโสและลูเซียสจะเริ่มสงครามอีกครั้ง คุณไม่ต้องการเห็นการก่อการกบฏที่เลือดเยอะอีกแล้วใช่ไหม?",
  ui_story_5076_50761102_41_dialog_content = "ดังนั้น... โปรดยกโทษให้ฉันด้วย",
  ui_story_5076_50761102_42_dialog_content = "ถึงแม้ว่าการทำความสะอาดจะเป็นความเจ็บปวด แต่ทุกสิ่งที่เราสามารถทำได้ตอนนี้คือทนมัน—",
  ui_story_5076_50761200_1_dialog_content = "<color=#e8d9bb>การที่ฮีโร่สูญเสียการควบคุมไปอย่างรวดเร็ว ทำให้ความหวาดกลัวกระจายไปทั่วอาณาจักร มีการร้องเรียนเข้ามาที่กรุงเทพจากทุกมุม</color>",
  ui_story_5076_50761200_2_dialog_content = "<color=#e8d9bb>ฟรอสต์ไฟร์, ผู้ที่เริ่มต้นทุกอย่าง, ตอนนี้ถูกโซ่มัดและถูกบังคับให้ \"ต่อสู้ต่อไป\" ภายใต้การสังเกตของอาณาจักร</color>",
  ui_story_5076_50761200_3_dialog_content = "<color=#e8d9bb>ส่วนที่เหลือของ Silent Hunters ถูกแยกและปรับใช้เพื่อปกครองเมืองชายแดน แม้แต่ Caelestites ที่อยู่ใกล้ ๆ ยังถูกกักบริเวณในบ้าน</color>",
  ui_story_5076_50761200_4_dialog_content = "ไปให้พ้น! เก็บของน่าสยองนั้นให้ห่างจากที่ของเรา.",
  ui_story_5076_50761200_5_dialog_content = "ฉันแค่ทหารและนี่คืออาวุธของฉัน ถ้าคุณปฏิเสธที่จะทำธุรกิจกับฉัน อย่างน้อยก็ปล่อยภรรยาของฉันเข้าไป",
  ui_story_5076_50761200_6_dialog_content = "ภรรยา...? ยัยบ้าจริงๆ ไปหายไปสิ!",
  ui_story_5076_50761200_7_dialog_content = "คุณควรปรับเปลี่ยนทัศนคติและยกเลิกความคิดเห็นที่หยาบคายของคุณ",
  ui_story_5076_50761200_8_dialog_content = "ปล่อยมันไปสิ, อาดราส... คุณยังคงเป็นผู้ปกป้องของพวกเขาอยู่ ดังนั้นการทะเลาะกับพวกเขาเรื่องเหล่านี้ก็ไม่มีประโยชน์",
  ui_story_5076_50761200_9_dialog_content = "... ดี.",
  ui_story_5076_50761200_10_dialog_content = "ดูเหมือนว่าข่าวลือเป็นจริง นักล่าผู้เงียบงันก็จริงๆ แล้วเป็นกลุ่มคนบ้าหมดเลย...",
  ui_story_5076_50761200_11_dialog_content = "ฉันไม่ชอบที่นี่นะ มาร์เซลา",
  ui_story_5076_50761200_12_dialog_content = "ไม่เป็นไรนะ อาดราส พวกเขาแค่ไม่เข้าใจคุณ นั่นแหละ",
  ui_story_5076_50761200_13_dialog_content = "ฉันแน่ใจว่าพวกเขาจะดูแลคุณดีขึ้นถ้าพวกเขามีโอกาสทำความรู้จักคุณ—",
  ui_story_5076_50761200_14_dialog_content = "ดูสิ, หมอนั่นอยู่ที่นั่นอีกแล้ว...",
  ui_story_5076_50761200_15_dialog_content = "เอิ่ม, เขาดูเหมือนจะสูญเสียได้ทุกเวลา ไม่รู้ว่าเขาจะ...เมื่อไหร่",
  ui_story_5076_50761200_16_dialog_content = "ทุกคนเป็นอย่างไรบ้างวันนี้?",
  ui_story_5076_50761200_17_dialog_content = "หายไป! เคลื่อนไหว!",
  ui_story_5076_50761200_18_dialog_content = "...",
  ui_story_5076_50761200_19_dialog_content = "อย่าท้อใจนะ บางทีคุณอาจจะพบกับคนที่ดีกว่าในครั้งหน้านะ?",
  ui_story_5076_50761200_20_dialog_content = "<color=#e8d9bb>ฮีโร่ยังคงยึดติดกับความหวังที่มืดมัว และปรารถนาให้มีใครสักคนมาช่วยเหลือ</color>",
  ui_story_5076_50761200_21_dialog_content = "ดูสิ, \"Eclipsite\" กำลังมาที่นี่.",
  ui_story_5076_50761200_22_dialog_content = "อิคลิพไซท์? ที่ไหนนะ?",
  ui_story_5076_50761200_23_dialog_content = "ลูกๆ มาอยู่ข้างหลังฉัน! มาร์เซล่า คุณก็เช่นกัน!",
  ui_story_5076_50761200_24_dialog_content = "ฉันจะจัดการอิคลิพไซท์—",
  ui_story_5076_50761200_25_dialog_content = "ฮ่า! งี่เง่า!",
  ui_story_5076_50761200_26_dialog_content = "คนโง่เหมือนอิคลิพไซท์เลย! ฮ่าฮ่าฮ่า!",
  ui_story_5076_50761200_27_dialog_content = "เด็ก ๆ พวกนั้น... พวกเขาเริ่มคิดเหมือนผู้ใหญ่หรือยัง?",
  ui_story_5076_50761200_28_dialog_content = "ฉันทำอะไรผิดเหรอ?",
  ui_story_5076_50761200_29_dialog_content = "<color=#e8d9bb>สถานการณ์นี้ยังคงต่อไปวันต่อวัน...</color>",
  ui_story_5076_50761200_30_dialog_content = "ทำไมทุกคนที่นี่ถึงกลัวฉัน...?",
  ui_story_5076_50761200_31_dialog_content = "นี่เป็นเพราะรอยแผลเป็นที่ถูกสาปนี้หรือ...?",
  ui_story_5076_50761200_32_dialog_content = "ฉันไม่ใช่อิคลิพไซท์! ฉันรู้ว่าฉันไม่ใช่—",
  ui_story_5076_50761200_33_dialog_content = "เห็นมั้ย? คนนั้นจะเป็นบ้าไปโดยไม่มีเหตุผล",
  ui_story_5076_50761200_34_dialog_content = "ได้ยินเรื่องเกี่ยวกับ Silent Hunter ที่ทำแบบนั้น ไหม ในที่สุดก็ได้เผาเมืองทั้งเมืองลง",
  ui_story_5076_50761200_35_dialog_content = "ไม่รู้ว่าทำไมฝ่าบาทยังคงเก็บพวกเขาไว้; เขาใจดีเกินไป",
  ui_story_5076_50761200_36_dialog_content = "<color=#e8d9bb>เขายังคงรับการโจมตีจากด้านหลัง ซึ่งเขาไม่สามารถป้องกันได้เลย</color>",
  ui_story_5076_50761200_37_dialog_content = "ถ้าถามฉัน พวกเขาควรถูกประหารทั้งหมด ใครจะรู้ว่าพวกเขาเคยเป็นอะไรบ้าง?",
  ui_story_5076_50761200_38_dialog_content = "\"Marcela\" คือใครนะ? เมื่อผู้ชายคนนั้นเรียกชื่อนี้ เขาดูเศร้ามาก...",
  ui_story_5076_50761200_39_dialog_content = "อาจจะเป็นใครสักคนที่มันเคยฆ่าไป จิตวิญญาณที่น่าสงสาร ได้ยินว่าบางอิคลิพไซท์เข้าใจเกี่ยวกับจักรวาล และพวกมันใช้ความเท็จหลอกลวงคนอื่นเพื่อให้สามารถเข้าใกล้พวกเขาได้",
  ui_story_5076_50761200_40_dialog_content = "จริงหรือ? น่ากลัวเกินไปใช่มั้ยล่ะ?",
  ui_story_5076_50761200_41_dialog_content = "<color=#e8d9bb>ดวงดาวที่เคยสว่างไว้ก็กำลังเลือนหายอย่างรวดเร็ว</color>",
  ui_story_5076_50761200_42_dialog_content = "มาร์เซลา... นี่เป็นสิ่งที่เกิดขึ้นกับฟรีกซันและคนอื่น ๆ หรือไม่? นี่คือวิถีชีวิตที่พวกเขานำไปสู่หรือไม่?",
  ui_story_5076_50761200_43_dialog_content = "ในตอนนั้น ฉันไม่รู้ว่าเธอรู้สึกอย่างไร",
  ui_story_5076_50761200_44_dialog_content = "ถ้าฉันเข้าใจในตอนนั้น ฉันอาจจะอยู่ข้างเธอได้ สิ่งที่เกิดขึ้นกับเธอจะมีทางเลือกอื่นไหมนะ?",
  ui_story_5076_50761200_45_dialog_content = "<color=#e8d9bb>แล้วหลังจากนั้น หัวใจของดวงดาวเหล่านั้นถูกจับและดึงลงสู่นรก</color>",
  ui_story_5076_50761200_46_dialog_content = "โอ๊ะ, มาร์เซลา? ฉันได้รับจดหมายจากลูดไวส์วันนี้แล้วนะ.",
  ui_story_5076_50761200_47_dialog_content = "ดูเหมือนว่าเธอสุดท้ายก็ได้โอกาสที่จะหลุดพ้น และเธอกำลังจะมาเยี่ยมเราเร็วๆ นี้ แต่ก็ยังอยากให้เธอไปเยี่ยมเพื่อนบ้านเก่าของเธอก่อน—",
  ui_story_5076_50761200_48_dialog_content = "หืม? คุณทำอะไรอยู่เหรอ?",
  ui_story_5076_50761200_49_dialog_content = "\"มาร์—เซ—ลา—\"",
  ui_story_5076_50761200_50_dialog_content = "มีการตอบสนอง! โอ้ไม่, เขากำลังมองมาทางนี้! วิ่งเร็ว!",
  ui_story_5076_50761200_51_dialog_content = "อะไร... ฉันคืออะไรสำหรับพวกเขากันแน่?",
  ui_story_5076_50761200_52_dialog_content = "แล้วทำไมคุณหยุดกระซิบลงที่หูฉันล่ะ? มาร์เซลา...",
  ui_story_5076_50761200_53_dialog_content = "<color=#e8d9bb>เมื่อดวงดาวลาดตระเวนท้องฟ้าและตกลงสู่โลก พวกมันจะสามารถกลับไปสู่ความสงบที่พวกมันคู่ควรได้หรือไม่? หรือเพียงแค่การตกจากสวรรค์ที่ห่างไกล?</color>",
  ui_story_5076_50761200_54_dialog_content = "<color=#e8d9bb>ดวงดาวที่เคยส่องสว่างให้กับมวลมนุษย์ พวกเขาจะหาที่อยู่ที่เหมาะสมได้หรือไม่?</color>",
  ui_story_5076_50761200_55_dialog_content = "<color=#e8d9bb>ถ้าอนาคตเหลือแต่ความสิ้นหวังเมื่อความฝันที่สวยงามถูกทำลาย... การต่อสู้ยังมีความหมายอยู่หรือไม่ในขณะนั้น?</color>",
  ui_story_5076_50761200_56_dialog_content = "ไปให้พ้นฉัน เด็กบ้า! หยุดตามฉันทันที!",
  ui_story_5076_50761200_57_dialog_content = "\"มาร์เซลา—มาร์เซลา—\"",
  ui_story_5076_50761200_58_dialog_content = "ดูเหมือนเขากำลังจะร้องไห้",
  ui_story_5076_50761200_59_dialog_content = "รีบเถอะ ไปกัน! \"Eclipsite\" กำลังจะหงุดหงิดล่ะ",
  ui_story_5076_50761200_60_dialog_content = "ตาย... ตาย... ตาย... ตาย—",
  ui_story_5076_50761200_61_dialog_content = "<size=45>อิคลิพไซท์!!!</size>",
  ui_story_5076_50761200_62_dialog_content = "ฉันไม่เห็นมัน... อิคลิพไซท์อยู่ที่ไหนนะ?",
  ui_story_5076_50761200_63_dialog_content = "แล้วเธออยู่ที่ไหน มาร์เซลา?",
  ui_story_5076_50761200_64_dialog_content = "โปรด...เพียงแค่เรียกฉันเหมือนเดิม...",
  ui_story_5076_50761300_1_dialog_content = "<color=#e8d9bb>อำนาจของราชอาณาจักรนั้นควรจะมีการสมดุลที่ละเอียดอ่อน แต่ท่าทีที่ยืนกรานของพระราชาได้ทำลายสภาผู้แก่ที่เขาเกลียดชังลงท้าย</color>",
  ui_story_5076_50761300_2_dialog_content = "<color=#e8d9bb>ตั้งแต่การขับไล่พระครูผู้ใหญ่ พระสงฆ์ลูเซียสได้เริ่มการล้างสารพัดของเขา</color>",
  ui_story_5076_50761300_3_dialog_content = "<color=#e8d9bb>การกระทำของพระมหาสงฆ์จริงๆ แล้วเกิดจากเจตนาที่เห็นแก่ตัวเองหรือไม่? หรือเขาเป็นแค่ตัวแทนที่พูดให้คนอื่นตลอดเวลา?</color>",
  ui_story_5076_50761300_4_dialog_content = "เปิดออกมานะ, อาดราส.",
  ui_story_5076_50761300_5_dialog_content = "พวกคุณคือใคร? รอสักครู่... กัปตัน?",
  ui_story_5076_50761300_6_dialog_content = "เป็นอะไรไป? คุณลืมหน้าของเราไปแล้วหรือ?",
  ui_story_5076_50761300_7_dialog_content = "นั่นเข้มข้นเกินไปนะ รองผู้กำกับไวซ์ โดยเฉพาะเมื่อพวกเรามาหาที่หลบภัยที่นี่กับคุณ",
  ui_story_5076_50761300_8_dialog_content = "แล้วเกิดอะไรขึ้น",
  ui_story_5076_50761300_9_dialog_content = "ความผิดปกติของกบฏถูกเปิดเผยภายในสภาผู้แก่ ภายใต้คำสั่งลับจากพระราชา ลูเซียสต้องการใช้นักล่าผู้เงียบงันเพื่อปราบปรามมัน",
  ui_story_5076_50761300_10_dialog_content = "แต่ฟรีกสันและเฟรยาปฏิเสธที่จะปฏิบัติตาม และผลที่ตามมา... พวกเขาถูกจับกุมและติดคุก",
  ui_story_5076_50761300_11_dialog_content = "ฉันปฏิเสธที่จะปล่อยเปลวไฟของฉันลงบนคน แม้ว่าจะหมายความว่าฉันต้องตาย",
  ui_story_5076_50761300_12_dialog_content = "นั่นคือเวลาที่อคิลลีสจัดการช่วยชีวิตอันตราย และช่วยฉันหลุดพ้นจากการกักขังในบ้านอีกด้วย",
