  ui_story_5076_50761300_101_dialog_content = "เอาเถอะ แต่ถ้าคุณไม่หยุดร้องไห้ หน้ากระดาษของคุณก็จะเปียกทั้งหมดนะ",
  ui_story_5076_50761300_102_dialog_content = "คุณสามารถดื้อรั้นได้บางครั้งนะ ลูดไวส์... ดังนั้น มาทำมันด้วยกันเถอะ",
  ui_story_5076_50761300_103_dialog_content = "ยังไงซะ... คงไม่มีใครคนใดที่จะสามารถเขียนความทรงจำทั้งหมดของพวกเราไว้ได้หมดเลยใช่ไหม?",
