  ui_story_5076_50761400_106_dialog_content = "นั่นมัน... นักล่าผู้เงียบงันเหรอเนี่ย?",
  ui_story_5076_50761400_107_dialog_content = "น่ากลัวมาก ยากที่จะเชื่อว่าเขาคือฮีโร่ตำนาน ดูที่เขาสิ! เขาเป็น... <color=#FFB400>บ้า</color> โดยสิ้นเชิง!",
  ui_story_5076_50761400_108_dialog_content = "ถ้าคุณปฏิเสธไม่ทำธุรกิจกับฉัน อย่างน้อยก็ปล่อยให้ภรรยาของฉันเข้าไป",
