  ui_story_5076_50761500_65_dialog_content = "ราชอาณาจักรกำลังจมอยู่ในความวุ่นวายอีกครั้ง ฉันไม่สามารถทิ้งมันไปได้แบบนี้",
  ui_story_5076_50761500_66_dialog_content = "พระสงฆ์ผู้ขี้ขลาดนั้นสามารถหนีไปได้... ดูเหมือนว่าทุกอย่างมีความเกี่ยวข้องอย่างใกล้ชิดกับราชา จริงๆแล้วเราไม่มีทางที่จะทำอะไรได้หรือ?",
  ui_story_5076_50761500_67_dialog_content = "ฉัน...ฉันได้สาบานว่าจะไม่ทำร้ายชาวเมือง ดังนั้นจงนับฉันออกไป",
  ui_story_5076_50761500_68_dialog_content = "ลืมมันไปเถอะ ซินเธีย การเผชิญหน้ากับกษัตริย์ไม่ได้เปลี่ยนแปลงอะไร แม้ว่าเราจะสามารถแก้แค้นเขาได้ มันก็จะสร้างความวุ่นวายให้กับราชอาณาจักรเพิ่มขึ้นเท่านั้น",
  ui_story_5076_50761500_69_dialog_content = "ความจริงคือ ราชากำลังพยายามยึดครองอำนาจของเขา นอกจากนี้ เขาย่อมมีคุณสมบัติที่จะนำพาประชาชนของเขาได้เป็นอย่างดี",
  ui_story_5076_50761500_70_dialog_content = "แต่ประชาชนของเขาไม่ควรได้รับความยุติธรรมเหมือนกันหรือ? ถ้าไม่มีการดำเนินการใด ๆ พวกเขาจะป้องกันไม่ให้คนอื่นๆ บาดเจ็บได้อย่างไร?",
  ui_story_5076_50761500_71_dialog_content = "ราชอาณาจักรกำลังสลายละลาย และเราถูกมองว่าเป็นอสูรเท่านั้น ไม่มีเหตุผลใด ๆ ที่เราจะต้องปลุกปั่นเปลวไฟ",
