  ui_story_5076_50761601_62_dialog_content = "<color=#e8d9bb>ความหลงใหลในใจ Friegson ได้ถูกไฟกลืนกินไปนานแล้ว ทิ้งเศษเถ้าถ่านเพียงห handful อยู่เฉยๆ</color>",
  ui_story_5076_50761601_63_dialog_content = "<color=#e8d9bb>ดังนั้น อารมณ์เดียวที่เหลือเพื่อจำปิดเธออาจเป็นความเกลียดชัง</color>",
  ui_story_5076_50761601_64_dialog_content = "<color=#e8d9bb>เคเลสไทต์ธรรมดาไม่สามารถทำได้เหมือนนี้ ยิ่งแล้วแต่คนที่ถูกคราบแผลเก่าครอบครอง</color>",
  ui_story_5076_50761601_65_dialog_content = "<color=#e8d9bb>อย่างไรก็ตาม, ถ้าเคเลสไทต์ยินยอมสละชีวิตของตนเอง ไหม้ตัวเองเพื่อรักษาอารมณ์ของผู้อื่น...</color>",
  ui_story_5076_50761601_66_dialog_content = "นอนเถอะ!",
  ui_story_5076_50761601_67_dialog_content = "ทะ... ทำไม...?",
  ui_story_5076_50761601_68_dialog_content = "คุณสามารถพักผ่อนได้เลยตอนนี้ ฟรีกสัน ฉันสัญญาว่าฝันของคุณจะไม่มีความเศร้าสลดตั้งแต่นี้ไปเลย",
  ui_story_5076_50761601_69_dialog_content = "ไม่เป็นไร... ตราบใดที่คุณคือคนที่ทรยศฉัน... ฉันไม่มีปัญหา...",
  ui_story_5076_50761601_70_dialog_content = "ท่านกัปตันทำอะไรกับฟรีกซันไปแล้ว? ทำไมถึงจะซุ่มโจมตีเธออย่างนี้เนี่ย?!",
  ui_story_5076_50761601_71_dialog_content = "ยังอยู่ในความมืดอยู่หรือ? พระราชาต้องการจะกำจัดพวกสัตว์ร้ายอย่างคุณ และอคิลลีสได้เลือกที่จะอยู่ด้านของพระราชาของเขา",
  ui_story_5076_50761601_72_dialog_content = "ลูเซียส? ทำไมคุณยังไม่ตาย...?",
  ui_story_5076_50761601_73_dialog_content = "นายจะไม่ปฏิเสธคำพูดของเขาใช่ไหม นายผู้กำกับ? แค่บอกฉันว่าเขาโกหก แล้วฉันจะเชื่อนาย!",
  ui_story_5076_50761601_74_dialog_content = "ยาม! จับกุมพวกผิดกฎหมายนี้!",
  ui_story_5076_50761601_75_dialog_content = "ที่เหลือให้เป็นหน้าที่ของท่าน กัปตัน ข้าวางใจว่าท่านจะไม่ทำให้พระองค์ผิดหวัง ใช่ไหมครับ?",
  ui_story_5076_50761601_76_dialog_content = "กัปตัน!!!",
  ui_story_5076_50761601_77_dialog_content = "อิคลิพไซท์พวกนี้ดูแข็งแกร่งกว่าเดิม! ซินเธีย, อยู่ในตำแหน่งของคุณ...",
  ui_story_5076_50761601_78_dialog_content = "ระวัง!",
  ui_story_5076_50761601_79_dialog_content = "ซินเธีย? เธอ...",
  ui_story_5076_50761601_80_dialog_content = "เหมือนที่ฉันบอกไว้แล้วนะ ฟรีย่า... ฉันจะไปก่อนเธอ ถ้ามีอนาคตสำหรับเราอยู่ที่นั้น ฉันหวังว่าเธอจะ—",
  ui_story_5076_50761601_81_dialog_content = "ซินเธีย!",
  ui_story_5076_50761601_82_dialog_content = "เหมือนที่ฉันเคยบอกไว้ ฉันมีหน้าที่ทำลายภัยอันตรายทุกอย่างที่คุกคามอาณาจักร",
  ui_story_5076_50761601_83_dialog_content = "ฉันไม่ใช่กัปตันของคุณอีกต่อไป ฉันเป็นผู้ประหารชีวิตที่รับใช้ราชอาณาจักร",
  ui_story_5076_50761601_84_dialog_content = "มาสิ, รีกัล.",
  ui_story_5076_50761601_85_dialog_content = "ตอนนี้ที่คุณที่สุดท้ายได้จำได้แล้ว รวบรวมความโกรธแค้นและความเกลียดชังทั้งหมดของคุณ... แล้วปล่อยมันลงบนฉัน",
  ui_story_5076_50761601_86_dialog_content = "<size=45>คุณ—</size>",
  ui_story_5076_50761601_87_dialog_content = "<size=45>เคลย์มอร์—!!!</size>",
  ui_story_5076_50761602_1_dialog_content = "<color=#e8d9bb>แม้ว่าอาดราสจะแสดงออกถึงความอ่อนแอในอารมณ์ของเขา แต่ความแข็งแกร่งและความมุ่งมั่นในการต่อสู้ของเขานั้นยิ่งนัก</color>",
  ui_story_5076_50761602_2_dialog_content = "<color=#e8d9bb>เพื่อครอบครองดาบที่เก็บความทรงจำสุดท้ายของอาดราส อคิลลีสตั้งใจรับการโจมตีจากดาบนั้น</color>",
  ui_story_5076_50761602_3_dialog_content = "ยกโทษให้ฉัน... อาดราส.",
  ui_story_5076_50761602_4_dialog_content = "<color=#e8d9bb>หลังจากที่เขาแทงดาบที่เพิ่งจับได้กลับเข้าไปในอาดราส พลังของเขาก็สูญหายทันที ทำให้เขาล้มลงบนพื้น</color>",
  ui_story_5076_50761602_5_dialog_content = "<color=#e8d9bb>ในเวลาเดียวกัน การตั้งเป้าหมายของตราประทับที่เอาไว้สำหรับเฟรยาและซินเธียก็เสร็จสมบูรณ์แล้ว</color>",
  ui_story_5076_50761602_6_dialog_content = "คุณทำได้ดีมาก หัวหน้าที่ภักดีของพระราชา ตอนนี้จงกำจัดสัตว์ประหลาดเหล่านี้ให้หมดเถอะ!",
  ui_story_5076_50761602_7_dialog_content = "กัปตันอคิลลิส... ทำไม...?",
  ui_story_5076_50761602_8_dialog_content = "ลูดวีสบอกว่านี่คือทางเดียวที่จะเปลี่ยนแปลงชะตากรรมของเรา อาดราส... แต่ไม่ต้องห่วง เราจะได้เจอกันอีกสักวัน",
  ui_story_5076_50761602_9_dialog_content = "เมื่อวันนั้นมาถึง ฉันหวังว่าคุณจะพบความสุขของคุณอีกครั้ง",
  ui_story_5076_50761602_10_dialog_content = "จบแล้วหรือยังนะ, ลัดไวส์?",
  ui_story_5076_50761602_11_dialog_content = "วิญญาณของพวกเขาถูกปิดตายอยู่ภายในร่างกายที่ไม่เคยตายของพวกเขา... ที่พวกเขาจะนอนหลับ... จนกระทั่ง...",
  ui_story_5076_50761602_12_dialog_content = "คุณบอกว่าการหลับฝันลึกนี้ ร่วมกับการเสื่อมโทรมของพวกเขา มีโอกาสทำลายความทรงจำ และแม้กระทั่งจิตสติของพวกเขา...",
  ui_story_5076_50761602_13_dialog_content = "แต่แม้แต่ถ้ามันเป็นอาดราส... เขามีความสุขน้อยมากในชีวิตของเขาอยู่แล้ว อย่างน้อย... เขาควรจะได้รับอนุญาตให้ยึดความทรงจำที่มีความสุขของเขาไว้ ใช่ไหม?",
  ui_story_5076_50761602_14_dialog_content = "ฉันขอโทษ... แต่ Caelestite ไม่ได้ทรงพลังทั้งหมด... ทุกสิ่งที่เราสามารถทำได้ตอนนี้... คือหวัง.",
  ui_story_5076_50761602_15_dialog_content = "หวังว่าความบ้าคลั่นของพวกเขาจะสิ้นสุดลงหลังจากพันปี... ถ้าพวกเขายังจำความทรงจำที่มีความสุขเพียงหนึ่งเดียวได้ในตอนนั้น... ทุกอย่างจะคุ้มค่าทั้งหมด",
  ui_story_5076_50761602_16_dialog_content = "โอย, ฉันเกือบจะถึงขีดจำกัดแล้ว... แต่ฉันยังไม่ได้ไปถึง Adras...",
  ui_story_5076_50761602_17_dialog_content = "(มองขึ้นไปที่ท้องฟ้า และดวงดาวจะส่องสว่างตอบสนอง)",
  ui_story_5076_50761602_18_dialog_content = "(ความอบอุ่นของแสงของพวกเขายังคงเดิมอยู่ แม้หลังจากพันปี)",
  ui_story_5076_50761602_19_dialog_content = "(คราวนี้ให้ฉันช่วยคุณ!)",
  ui_story_5076_50761602_20_dialog_content = "เสียงนี้... คุณมาจากยุคที่ห่างไกลนั้นรึเปล่า?",
  ui_story_5076_50761602_X20_dialog_content = "ตื่นสิ รีกัล!",
  ui_story_5076_50761602_X21_dialog_content = "เรามาดูพวกเขาด้วยกันเถอะ... <color=#FFB400>รีกัล</color>.",
  ui_story_5076_50761602_21_dialog_content = "ฉันเห็นแล้ว... ดูเหมือนว่าความพยายามของฉันไม่ได้เป็นสิ่งที่ไร้ค่าหลังจากทั้งหมด...",
  ui_story_5076_50761602_22_dialog_content = "ความทรงจำที่สุกสีดาวนั้นผ่านการทดสอบของเวลา และตอนนี้ที่สุดก็อยู่ในมือของเคเลสไทต์คนอื่น...",
  ui_story_5076_50761602_23_dialog_content = "ฉันรู้สึกคิดถึงตลอดเวลานี้ และเสียงเหล่านั้นพยายามอย่างหนักเพื่อสื่อสารกับฉัน",
  ui_story_5076_50761602_24_dialog_content = "อารมณ์ความรู้สึกร่วมกันของเรามัดเราไว้ด้วยกัน สร้างสายสัมพันธ์ที่ล้ำหน้ากระแสเวลา...",
  ui_story_5076_50761602_25_dialog_content = "อาดราส! ฉันเห็นมันแล้ว... อนาคตนั้นมันจริงจัง",
  ui_story_5076_50761602_26_dialog_content = "หลายปีต่อไป จะมีคนรอคอยการกลับมาอย่างชัยชนะของคุณ",
  ui_story_5076_50761602_27_dialog_content = "ฉันไม่ต้องการ...",
  ui_story_5076_50761602_28_dialog_content = "ฉันไม่ต้องการชีวิตนิรันดร์ ฉันไม่ต้องการความเป็นนิรันดร์...",
  ui_story_5076_50761602_29_dialog_content = "ทั้งหมดที่ฉันต้องการ...คือช่วงเวลาที่หลุดมือฉัน...นั่นแหละ...ทั้งหมดที่ฉันต้องการคือมาร์เซลา",
  ui_story_5076_50761602_30_dialog_content = "ดังนั้นโปรด... ปล่อยฉันไปเถอะ! ฉันไม่อยากถูกกักขัง! ปล่อยให้ฉันได้นอนอยู่ข้างๆ มาร์เซล่าและหลับไปตลอดเวลา!",
  ui_story_5076_50761602_31_dialog_content = "ถ้านั่นคือสิ่งที่คุณต้องการ...",
  ui_story_5076_50761602_32_dialog_content = "ช่วยฉันด้วย มาร์เซลา... และคุณด้วย เพื่อนรักที่อยู่ไกล—",
  ui_story_5076_50761602_33_dialog_content = "ช่วยฉันเปลี่ยนความปรารถนาของเขาให้เป็นพลังที่เขาต้องการเพื่อการอยู่รอด!",
  ui_story_5076_50761602_34_dialog_content = "(ให้คนที่อยู่ในความทรงจำของเขาอยู่ข้างๆ เขา—)",
  ui_story_5076_50761602_35_dialog_content = "... มาร์เซลา?",
  ui_story_5076_50761602_36_dialog_content = "อย่าร้องไห้นะ อาดราส... ฉันอยู่ตรงนี้...",
  ui_story_5076_50761602_37_dialog_content = "เดี๋ยวก่อน มาร์เซลา อย่าเพิ่งไปสิ!",
  ui_story_5076_50761602_38_dialog_content = "ฉันจะไม่ไปไหนเลย อาดราสที่รัก ฉันจะอยู่กับคุณเสมอ ตอนนี้และตลอดไป...",
  ui_story_5076_50761602_39_dialog_content = "เลยอย่ากลัว... เพื่อนของคุณทุกคนต่างอยากให้คุณนอน ตอนนี้พักหัวที่เหนื่อยล้าของคุณเถอะ...",
  ui_story_5076_50761602_40_dialog_content = "นอน... เพื่อให้เราสุดท้ายก็—",
  ui_story_5076_50761602_41_dialog_content = "ไม่นะ! ได้โปรด!",
  ui_story_5076_50761602_42_dialog_content = "มาร์เซลา! อย่าไปสิ!",
  ui_story_5076_50761602_43_dialog_content = "อย่าร้องไห้ อาดราส",
  ui_story_5076_50761602_44_dialog_content = "ความทรงจำของเรา, ความมุ่งมั่นของเรา... แม้กระทั่งศรัทธาของเรา.",
  ui_story_5076_50761602_45_dialog_content = "เราจะทิ้งทุกอย่างให้มาร์เซลา ดังนั้นเธอจึงสามารถอยู่เคียงข้างคุณเสมอ",
  ui_story_5076_50761602_46_dialog_content = "ตราบใดที่คุณยังมีความผูกพันกับโลกนี้เล็กน้อยและยินดีที่จะวางศรัทธาในความหวัง",
  ui_story_5076_50761602_47_dialog_content = "(ความฝันของคุณจะไม่เคยเหงา)",
  ui_story_5076_50761602_48_dialog_content = "คุณจะอยู่ด้วยกันเสมอ",
  ui_story_5076_50761602_49_dialog_content = "(มากับฉันสิ, <color=#FFB400>อาดราส</color>. ได้เวลาตื่นจาก<color=#FFB400>ความฝัน</color>พันปีของคุณแล้ว—)",
  ui_story_5076_50761602_50_dialog_content = "เมื่อคุณสุดท้าย<color=#FFB400>ตื่น</color>ขึ้นมา คุณอาจจะไม่จำอะไรได้ ถ้าเกิดเช่นนั้น กรุณาอย่าเศร้านะคะ",
  ui_story_5076_50761602_51_dialog_content = "ความทรงจำที่มีค่านั้นจะอยู่ในหัวใจของคุณตลอดไป, อาดราส",
  ui_story_5076_50761602_52_dialog_content = "ความรู้สึกที่เกี่ยวข้องกับพวกเขาจะเป็นส่วนหนึ่งของวิญญาณของคุณเสมอ",
  ui_story_5076_50761602_53_dialog_content = "คุณจะไม่โดดเดี่ยวอีกต่อไป",
  ui_story_5076_50761602_54_dialog_content = "ตอนนี้ขอร้องนะ ให้ความสบายใจแล้วก็ไปนอนเถอะ...",
  ui_story_5076_50761602_55_dialog_content = "จะมี<color=#FFB400>บ้าน</color>สำหรับคุณในวันหนึ่ง ถ้าคุณยังคงความหวังอยู่ในหัวใจ และเมื่อคุณพบมัน ความสงบจะกลับมาหาคุณ—",
  ui_story_5076_50761602_56_dialog_content = "Marcela... ทุกคน...",
  ui_story_5076_50761602_57_dialog_content = "*อะแฮ่ม* ฉันขอโทษนะ อคิลลีส",
  ui_story_5076_50761602_58_dialog_content = "แต่ดูเหมือนว่า... การเดินทางของฉันกำลังจะจบลงแล้ว",
  ui_story_5076_50761602_59_dialog_content = "ลูดวีส... นี่คือราคาที่ต้องจ่ายหรือ? ฉันเข้าใจแล้ว... แม้แต่เคเลสไทต์ก็ไม่สามารถทนต่อความเศร้าโศกมากเท่านี้...",
  ui_story_5076_50761602_60_dialog_content = "นั่นเป็นเหตุผลที่... ฉันฝากอนาคตไว้ในมือคุณแล้ว",
  ui_story_5076_50761602_61_dialog_content = "เราคู่ควรกับสิ่งนี้จริง ๆ หรือไม่?",
  ui_story_5076_50761602_62_dialog_content = "นั่นคือคำถามหรือเปล่า? ฮิฮิ... ฉันขอขอบคุณที่ได้รู้จักทุกคน ด้วยความช่วยเหลือจากคุณ ทำให้เคเลสไทต์ผู้ที่เดินทางอยู่นี้ สุดท้ายก็ได้ความกล้าที่จะมองขึ้นไปที่ดวงดาว",
  ui_story_5076_50761602_63_dialog_content = "ขอบคุณทุกคน... สำหรับการส่องสว่างแสงของคุณให้กับ<color=#FFB400>โลกนี้</color>.",
  ui_story_5076_50761602_64_dialog_content = "ฉันเข้าใจ... พักผ่อนให้สบายเถอะนะ ลัดไวส์",
  ui_story_5076_50761602_65_dialog_content = "ความทรงจำของคุณ, ความมุ่งมั่นของคุณ, ชีวิตของคุณ...",
